// Get the output from the previous node
let output = $input.item.json.output;

// Remove markdown code blocks (```json, ```, etc.)
output = output.replace(/```json\n?/g, '').replace(/```\n?/g, '');

// Trim whitespace
output = output.trim();

// Fix the corrupted data by removing the repeated "Page" and "mission" text
// This regex finds the pattern and cleans it up
output = output.replace(/"owner":\s*"[^"]*?(Page|mission|era|-de|готов|поste|deprecated|missionary)[^"]*"/g, function(match) {
  // Extract just the actual name before the corruption
  let cleanMatch = match.match(/"owner":\s*"([A-Za-z]+)/);
  if (cleanMatch && cleanMatch[1]) {
    return '"owner": "' + cleanMatch[1] + '"';
  }
  return '"owner": "Unassigned"';
});

// Also fix any corrupted deadline fields
output = output.replace(/"deadline":\s*"[^"]*?(Page|mission|era|-de|готов|поste|deprecated|missionary)[^"]*"/g, '"deadline": "Not specified"');

// Parse the cleaned JSON
try {
  const parsedData = JSON.parse(output);
  return parsedData;
} catch (error) {
  // If parsing still fails, return error info for debugging
  return {
    error: "JSON parsing failed",
    errorMessage: error.message,
    cleanedOutput: output,
    originalOutput: $input.item.json.output
  };
}

