=<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8" />
  <style>
    body {
      font-family: Arial, sans-serif;
      color: #333333;
      line-height: 1.6;
    }
    h2 {
      color: #1a73e8;
    }
    ul {
      padding-left: 20px;
    }
    table {
      border-collapse: collapse;
      width: 100%;
      margin-top: 10px;
    }
    th, td {
      border: 1px solid #dddddd;
      padding: 8px;
      text-align: left;
    }
    th {
      background-color: #f2f2f2;
    }
  </style>
</head>

<body>

  <h2>📌 Meeting Summary</h2>

  <p><strong>Meeting Title:</strong> {{ $json.meeting_title }}</p>

  <h3>✅ Key Decisions</h3>
  <ul>
    {{
      $json.key_decisions
        .map(decision => `<li>${decision}</li>`)
        .join('')
    }}
  </ul>

  <h3>📝 Action Items</h3>

  <table>
    <thead>
      <tr>
        <th>Task</th>
        <th>Owner</th>
        <th>Deadline</th>
      </tr>
    </thead>
    <tbody>
      {{
        $json.action_items
          .map(item => `
            <tr>
              <td>${item.task}</td>
              <td>${item.owner}</td>
              <td>${item.deadline}</td>
            </tr>
          `)
          .join('')
      }}
    </tbody>
  </table>

  <br />

  <p>Regards,<br/>
  <strong>Meeting Assistant</strong></p>

</body>
</html>
